CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.lead_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, lead_id uuid NOT NULL, added_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.lead_activity TO authenticated;
GRANT ALL ON public.lead_activity TO service_role;
ALTER TABLE public.lead_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_activity_read ON public.lead_activity FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
INSERT INTO public.lead_activity(user_id,lead_id,added_at) SELECT user_id,id,created_at FROM public.leads WHERE id NOT IN(SELECT id FROM public.lead_import_records);
CREATE FUNCTION public.record_lead_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.lead_activity(user_id,lead_id,added_at) VALUES(NEW.user_id,NEW.id,NEW.created_at); RETURN NEW; END $$;
CREATE TRIGGER leads_record_activity AFTER INSERT ON public.leads FOR EACH ROW EXECUTE FUNCTION public.record_lead_activity();
CREATE FUNCTION public.previous_version_leads() RETURNS TABLE(id uuid,facebook_link text,created_at timestamptz,serial integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.id,r.record->>'facebook_link',(r.record->>'created_at')::timestamptz,(r.record->>'serial')::integer FROM public.lead_import_records r WHERE auth.uid() IS NOT NULL ORDER BY r.id $$;
REVOKE ALL ON FUNCTION public.previous_version_leads() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.previous_version_leads() TO authenticated;
COMMENT ON FUNCTION public.collected_leads() IS 'DEPRECATED: app no longer lists all accounts leads; previous_version_leads provides original imported links only';